def recursive_list_sum(lst):
    """
    Recursively flattens a list (handling nested lists) and returns the sum of all numeric elements.

    :param lst: A list that may contain nested lists and numeric values (int or float).
    :return: The sum of all numeric elements after flattening.
    """
    def helper(current_list):
        total = 0
        for item in current_list:
            if isinstance(item, list):
                # Recursively process nested lists
                total += helper(item)
            elif isinstance(item, (int, float)):
                # Add numeric element
                total += item
            # Ignore other types if any
        return total

    return helper(lst)
