def max_product(nums):
    if not nums:
        return 0

    max_prod = min_prod = nums[0]
    result = nums[0]

    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            max_prod = max(max_prod, nums[i], max_prod * nums[i])
            min_prod = min(min_prod, nums[i], min_prod * nums[i])
        else:
            max_prod = max(max_prod, nums[i])
            min_prod = min(min_prod, nums[i])
        result = max(result, max_prod)

    return result
