def dict_depth(d):
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")
    if not d:
        return 0

    max_depth = 0

    for key, value in d.items():
        if isinstance(value, dict):
            child_depth = dict_depth(value)
            max_depth = max(max_depth, 1 + child_depth)
        elif isinstance(value, list):
            # For lists, we only care about nested dicts.
            # The depth contributed by a list is 1 + max depth of any dict inside.
            # If the list contains no dicts, the contribution is 1 (the list itself).
            dict_in_list = [item for item in value if isinstance(item, dict)]
            if dict_in_list:
                max_depth = max(max_depth, 1 + max(dict_depth(item) for item in dict_in_list))
            else:
                # List with no nested dicts adds 1 level (the list itself)
                max_depth = max(max_depth, 1)
        else:
            # Scalar values do not add depth
            pass

    return max_depth
```

