def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in collatz sequence.
    """
    if n <= 0:
        return []

    visited = set()
    current = n

    while current not in visited:
        visited.add(current)
        if current % 2 == 0:
            current //= 2
        else:
            current = 3 * current + 1

        if current == 1:
            break

    odd_numbers = sorted([x for x in visited if x % 2 == 1])
    return odd_numbers
```

