def add_nested_tuples(t1, t2):
    """
    Perform element-wise addition of two nested tuples of the same structure.

    Parameters:
        t1 (tuple): First nested tuple.
        t2 (tuple): Second nested tuple with the same structure as t1.

    Returns:
        tuple: A nested tuple where each element is the sum of corresponding elements in t1 and t2.

    Raises:
        ValueError: If the input tuples are not of the same structure or cannot be added.
    """
    def add_elements(a, b):
        if isinstance(a, tuple) and isinstance(b, tuple):
            if len(a) != len(b):
                raise ValueError("Nested tuples must have the same structure and length at each level.")
            return tuple(add_elements(x, y) for x, y in zip(a, b))
        else:
            # Attempt numeric addition; raise if types are incompatible
            try:
                return a + b
            except TypeError:
                raise ValueError(f"Cannot add {type(a).__name__} and {type(b).__name__}")

    if not isinstance(t1, tuple) or not isinstance(t2, tuple):
        raise TypeError("Both inputs must be tuples.")

    return add_elements(t1, t2)
