def bitwise_xor(*tuples):
    """
    Perform bitwise XOR across all given tuples element-wise.

    Each input tuple must have the same length.
    Returns a tuple containing the XOR result of corresponding elements.
    """
    if not tuples:
        return ()

    if not all(len(t) == len(tuples[0]) for t in tuples):
        raise ValueError("All input tuples must have the same length.")

    length = len(tuples[0])
    result = []

    for i in range(length):
        xor_val = 0
        for tup in tuples:
            xor_val ^= tup[i]
        result.append(xor_val)

    return tuple(result)
