    def get_prime_factors(n, factors=None):
        if factors is None:
            factors = []
        if n == 1:
            return factors
        for p in range(2, int(n**0.5) + 1):
            if n % p == 0:
                factors.append(p)
                return get_prime_factors(n // p, factors)
        factors.append(n)
        return factors

    prime_factors = get_prime_factors(a)
    if len(prime_factors) != 3:
        return False

    # Check if all factors are prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if all(is_prime(p) for p in prime_factors):
        return True
    return False
