def dict_depth(d):
    if not isinstance(d, dict):
        return 0

    max_depth = 0
    for key, value in d.items():
        if isinstance(value, dict):
            child_depth = dict_depth(value)
            max_depth = max(max_depth, 1 + child_depth)
        elif isinstance(value, list):
            # Depth of a list is 1 + max depth of its contents, but at minimum 1
            if not value:
                list_depth = 1
            else:
                max_in_list = 0
                for item in value:
                    if isinstance(item, dict):
                        depth = dict_depth(item)
                        max_in_list = max(max_in_list, 1 + depth)
                    else:
                        # Non-dict items contribute 0 to the max, but the list itself adds 1
                        pass
                list_depth = 1 + max_in_list if max_in_list > 0 else 1
            max_depth = max(max_depth, list_depth)

    return max_depth
