    Returns the n-th number that is both a Fibonacci number and prime.
    The sequence of prime Fibonacci numbers starts: 2, 3, 5, 13, 89, ...
    """
    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x == 2 or x == 3:
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        limit = int(x ** 0.5) + 1
        for i in range(5, limit, 6):
            if x % i == 0 or x % (i + 2) == 0:
                return False
        return True

