def max_product(nums):
    if not nums:
        return 0

    max_prod = float('-inf')
    n = len(nums)

    # For each starting index, extend while strictly increasing
    for i in range(n):
        curr = nums[i]
        prod = curr
        j = i + 1
        while j < n and nums[j] > nums[j-1]:
            prod *= nums[j]
            j += 1

        if prod > max_prod:
            max_prod = prod

    # If no valid subsequence found (e.g., empty or all non-positive with no increasing pair)
    if max_prod == float('-inf'):
        # Check if there is at least one positive element
        if any(x > 0 for x in nums):
            # At least one positive exists, so the max product will be positive
            return max_prod

    # If we have only non-positive numbers and no strictly increasing subsequence of length > 1,
    # the max product is the maximum single element (could be 0 or negative).
    return max(nums)
