def is_undulating(n: int) -> bool:
    """
    Check whether the given number is undulating.
    A number is undulating if its digits strictly alternate between increasing and decreasing.
    Undulating numbers must have at least three digits.
    """
    if n < 100:
        return False

    digits = []
    temp = n
    while temp > 0:
        digits.append(temp % 10)
        temp //= 10
    digits.reverse()

    if len(digits) != 3:
        for i in range(1, len(digits) - 1):
            if (digits[i] > digits[i - 1]) == (digits[i + 1] > digits[i]):
                return False
        return True
    else:
        first_change = digits[1] > digits[0]
        if first_change is True:
            return digits[2] < digits[1]
        else:
            return digits[2] > digits[1]
