def is_multiply_prime(a):
    """Returns True if the given number is the product of exactly three prime numbers
    (with repetition allowed), False otherwise.
    Assumes 2 <= a < 100.
    Example:
    is_multiply_prime(30) -> True (30 = 2 * 3 * 5)
    is_multiply_prime(12) -> True (12 = 2 * 2 * 3)
    """
    if a < 2:
        return False

    def is_prime(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def get_prime_factors(n):
        factors = []
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.append(d)
                n //= d
            d += 1
        if n > 1:
            factors.append(n)
        return factors

    prime_factors = get_prime_factors(a)
    if len(prime_factors) != 3 or not all(is_prime(p) for p in prime_factors):
        return False

    return True
