        else:
            left = mid + 1
    first = left if left < n and arr[left] == element else n

    if first == n or arr[first] != element:
        return False

    # Find the last occurrence of the element
    left, right = first, n - 1
    last = first - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] <= element:
            left = mid + 1
        else:
            right = mid - 1
    last = right if right >= first and arr[right] == element else first - 1

    if last < first:
        return False

    count = last - first + 1
    return count > n // 2
```

