            if not obj:
                return 0
            return 1 + max((get_depth(v) for v in obj.values()), default=0)
        elif isinstance(obj, (list, tuple)):
            return 0 if not obj else 1 + max((get_depth(item) for item in obj), default=0)
        else:
            return 0

