def next_smallest_palindrome(n: int) -> int:
    """
    Return the next smallest palindrome strictly greater than n.
    Uses a constructive approach based on palindrome structure to avoid brute-force iteration.
    """
    def to_list(x: int) -> list[int]:
        return list(str(x))

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    def build_next_palindrome(digits: list[int]) -> int:
        length = len(digits)
        half = length // 2
        half_part = digits[:half + 1]  # include middle digit for odd length

        half_int = int("".join(map(str, half_part)))

        if length % 2 == 0:
            mirrored = str(half_int)[::-1]
            result = half_part[:half] + list(mirrored)
        else:
            mirrored = str(half_int)[1:][::-1]
            result = half_part[:half] + list(mirrored)

        return int("".join(map(str, result)))

    def increment_number(digits: list[int]) -> list[int]:
        digits = digits.copy()
        i = len(digits) - 1
        while i >= 0:
            if digits[i] < 9:
                digits[i] += 1
                break
            digits[i] = 0
            i -= 1
        if i < 0:
            digits.insert(0, 1)
        return digits

    x = n + 1
    digits = to_list(x)

    while True:
        palindrome = build_next_palindrome(digits)
        if palindrome > n:  # strictly greater than n
            return palindrome
        digits = increment_number(digits)
