import math

def poly(xs: list, x: float) -> float:
    """
    Evaluates polynomial with coefficients xs at point x.
    Computes: xs[0] + xs[1]*x + xs[2]*x^2 + ... + xs[n]*x^n
    """
    return sum(coeff * math.pow(x, i) for i, coeff in enumerate(xs))


def find_zero(xs: list) -> float:
    """
    Finds a root x such that poly(x) = 0.
    Uses Newton-Raphson method starting from the largest non-zero coefficient.
    The input list xs has an even number of coefficients, with the last non-zero coefficient being the highest degree.
    Returns a single zero point.
    """
    def f(t: float) -> float:
        return poly(xs, t)

    def df(t: float) -> float:
        if len(xs) <= 1:
            return 0.0
        deriv_coeffs = [0.0] * (len(xs) - 1)
        for i in range(1, len(xs)):
            deriv_coeffs[i - 1] = i * xs[i]
        return poly(deriv_coeffs, t)

    # Find the largest non-zero coefficient index
    degree = -1
    for i, c in enumerate(xs):
        if c != 0:
            degree = i
    if degree == -1:
        raise ValueError("No non-zero coefficients found in the polynomial")

    # Start search from the largest non-zero coefficient
    x = degree

    # Perform Newton-Raphson iterations
    for _ in range(100):
        fx = f(x)
        dfx = df(x)
        if abs(dfx) < 1e-14:
            break
        x = x - fx / dfx
    return round(x, 2)
