def is_majority(arr, n, element):
    if n == 0:
        return False

    # Find the first occurrence using binary search
    left, right = 0, n - 1
    first = n
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] >= element:
            right = mid - 1
        else:
            left = mid + 1
    first = left if left < n and arr[left] == element else n

    # If element not found, it cannot be majority
    if first == n or arr[first] != element:
        return False

    # Find the last occurrence using binary search
    left, right = first, n - 1
    last = first - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] <= element:
            left = mid + 1
        else:
            right = mid - 1
    last = right if right >= first and arr[right] == element else first - 1

    count = last - first + 1
    return count > n // 2
```

