    Example:
    is_multiply_prime(30) -> True (30 = 2 * 3 * 5)
    is_multiply_prime(12) -> True (12 = 2 * 2 * 3)
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def get_prime_factors(n):
        factors = []
