def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = list(nums)  # dp[i] = max product of an increasing subsequence ending at i

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)
