import math

def is_simple_power(x, n):
    """Your task is to write a function that returns true if a number x is a simple
    power of n and false in other cases.
    x is a simple power of n if n**int=x
    For example:
    is_simple_power(1, 4) => true
    is_simple_power(2, 2) => true
    is_simple_power(8, 2) => true
    is_simple_power(3, 2) => false
    is_simple_power(3, 1) => false
    is_simple_power(5, 3) => false
    """
    if n == 0:
        return False
    if n == 1:
        return x == 1
    if n == -1:
        return x in (1, -1)
    if x == 0:
        return n == 0 and n != 1
    if x == 1:
        return n in (1, -1)
    if x == -1:
        return n == -1

    # For |n| >= 2, we can use logarithms to find the exponent k,
    # then verify by exponentiation to avoid floating point inaccuracies.
    try:
        k = math.log(abs(x), abs(n))
    except ValueError:
        return False

    k_rounded = round(k)
    if k_rounded < 0:
        return False

    if abs(k - k_rounded) > 1e-9:
        return False

    return x == n ** k_rounded
