import math

def poly(xs: list, x: float) -> float:
    """
    Evaluates polynomial with coefficients xs at point x.
    Computes: xs[0] + xs[1]*x + xs[2]*x^2 + ... + xs[n]*x^n
    """
    return sum(coeff * math.pow(x, i) for i, coeff in enumerate(xs))


def find_zero(xs: list) -> float:
    """
    Finds a root x such that poly(x) = 0.
    Uses a robust search strategy:
    1. Identifies the degree and signs of coefficients.
    2. Determines a safe interval [a, b] where the polynomial changes sign
       (using the property that the polynomial changes sign between 1 and 2 when
       the degree is even, or between 1 and -1 when the degree is odd).
    3. Uses bisection method within this interval to find a root.
    The input list xs has an even number of coefficients, with the last non-zero coefficient being the highest degree.
    Returns a single zero point.
    """
    def f(t: float) -> float:
        return poly(xs, t)

    # Find the degree (index of the last non-zero coefficient)
    degree = -1
    for i, c in enumerate(xs):
        if c != 0:
            degree = i
    if degree == -1:
        raise ValueError("No non-zero coefficients found in the polynomial")

    # Determine the interval [a, b] where the polynomial changes sign.
    # For polynomials with even degree, we know that f(1) and f(2) have opposite signs.
    # For polynomials with odd degree, we know that f(1) and f(-1) have opposite signs.
    if degree % 2 == 0:
        a, b = 1.0, 2.0
    else:
        a, b = 1.0, -1.0

    # Refine the interval to ensure f(a) and f(b) have opposite signs.
    while abs(f(b)) > 1e-10 and f(a) * f(b) > 0:
        if f(b) > 0:
            b *= 2.0

