def sumofFactors(n: int) -> int:
    """
    Returns the sum of all even factors of n.
    Factors are positive integers that divide n.
    Even factors are those divisible by 2.
    """
    if n <= 0:
        return 0

    # Prime factorization of n
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # If n is odd, it has no even factors.
    if 2 not in factors:
        return 0

    # Helper to compute sum of powers: (p^(k+1) - 1) // (p - 1)
    def sigma(p: int, k: int) -> int:
        return (pow(p, k + 1) - 1) // (p - 1)

    # Total sum of all divisors
    total_sum = 1
    for p, k in factors.items():
        total_sum *= sigma(p, k)

    # Sum of odd divisors (divisors of m only, where m = n / 2^e)
    odd_sum = 1
    for p, k in factors.items():
        if p == 2:
            continue
        odd_sum *= sigma(p, k)

    # Sum of even divisors = total_sum - odd_sum
    return total_sum - odd_sum
```

