    Depth is defined as the maximum number of nested dictionaries found.
    Lists/tuples inside dictionaries are counted towards depth, but primitives (int, str, etc.) do not increase depth.

    Depth rules:
    - Empty dict: depth 0
    - Non-dict, non-collection: depth 0
    - Dict: 1 + max depth of its values
    - List/Tuple: max depth of its items + 1 (if not empty), else 0
    """
    def get_depth(obj):
        if isinstance(obj, dict):
            if not obj:
                return 0
            return 1 + max(get_depth(v) for v in obj.values())
        elif isinstance(obj, (list, tuple)):
            if not obj:
                return 0
            return 1 + max(get_depth(item) for item in obj)
