def sumofFactors(n: int) -> int:
    """
    Returns the sum of all even factors of n.
    Factors are positive integers that divide n.
    Even factors are those divisible by 2.
    """
    if n <= 0:
        return 0

    # Find the exponent of 2 in the prime factorization of n
    count2 = 0
    temp = n
    while temp % 2 == 0:
        count2 += 1
        temp //= 2

    # Prime factorization of the odd part of n
    factors_odd = {}
    d = 3
    while d * d <= temp:
        while temp % d == 0:
            if d not in factors_odd:
                factors_odd[d] = 0
            factors_odd[d] += 1
            temp //= d
        d += 2
    if temp > 1:
        if temp not in factors_odd:
            factors_odd[temp] = 0
        factors_odd[temp] += 1

    # Helper to compute sum of powers: (p^(k+1) - 1) // (p - 1)
    def sigma(p: int, k: int) -> int:
        return (pow(p, k + 1) - 1) // (p - 1)

    # Total sum of all divisors of n
    total_sum = sigma(2, count2)
    for p, k in factors_odd.items():
        total_sum *= sigma(p, k)

    # Sum of odd divisors (divisors not divisible by 2)
    odd_sum = 1
    for p, k in factors_odd.items():
        odd_sum *= sigma(p, k)

    # Sum of even divisors = total_sum - odd_sum
    return total_sum - odd_sum
