def dict_depth(d):
    """
    Calculate the depth of a dictionary.

    Depth rules:
    - Empty dict: depth 0
    - Non-dict, non-collection: depth 0
    - Dict: 1 + max depth of its values
    - List/Tuple: max depth of its items + 1 (if not empty), else 0
    - This correctly handles nested lists/tuples within dictionaries.
    """
    def get_depth(obj):
        if isinstance(obj, dict):
            if not obj:
                return 0
            return 1 + max(get_depth(v) for v in obj.values())
        elif isinstance(obj, (list, tuple)):
            if not obj:
                return 0
            return 1 + max(get_depth(item) for item in obj)
        else:
            return 0

    if not isinstance(d, dict):
        return 0
    return get_depth(d)
