def numerical_letter_grade(grades):
    """Returns a list of letter grades corresponding to the input GPA list.

    Grading scale:
        >= 4.0      -> A+
        > 3.7       -> A
        > 3.3       -> A-
        > 3.0       -> B+
        > 2.7       -> B
        > 2.3       -> B-
        > 2.0       -> C+
        > 1.7       -> C
        > 1.3       -> C-
        > 1.0       -> D+
        > 0.7       -> D
        > 0.0       -> D-
        == 0.0      -> E
    """
    def gpa_to_letter(gpa):
        if gpa >= 4.0:
            return 'A+'
        elif gpa > 3.7:
            return 'A'
        elif gpa > 3.3:
            return 'A-'
        elif gpa > 3.0:
            return 'B+'
        elif gpa > 2.7:
            return 'B'
