def max_product(nums):
    if not nums or len(nums) == 0:
        return 0

    n = len(nums)
    # dp[i] stores the maximum product of an increasing subsequence ending at index i
    dp = list(nums)

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)
